package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	MaxMessageAge = 300 // seconds
	MACLength     = 32
	NonceSize     = 8
)

var (
	ErrInvalidSignature = errors.New("invalid signature")
	ErrExpiredMessage   = errors.New("message expired")
	ErrReplayDetected   = errors.New("replay detected")
)

// NonceCache prevents replay attacks
type NonceCache struct {
	mu    sync.RWMutex
	seen  map[string]int64
	ttl   int64
}

func NewNonceCache(ttl int64) *NonceCache {
	nc := &NonceCache{
		seen: make(map[string]int64),
		ttl:  ttl,
	}
	go nc.cleanup()
	return nc
}

func (nc *NonceCache) cleanup() {
	ticker := time.NewTicker(60 * time.Second)
	for range ticker.C {
		nc.mu.Lock()
		now := time.Now().Unix()
		for k, v := range nc.seen {
			if now-v > nc.ttl {
				delete(nc.seen, k)
			}
		}
		nc.mu.Unlock()
	}
}

func (nc *NonceCache) Check(nonce string) bool {
	nc.mu.Lock()
	defer nc.mu.Unlock()
	if _, exists := nc.seen[nonce]; exists {
		return false
	}
	nc.seen[nonce] = time.Now().Unix()
	return true
}

// Verifier handles HMAC-based request authentication
type Verifier struct {
	keys       map[string][]byte
	nonceCache *NonceCache
	mu         sync.RWMutex
}

func NewVerifier(keys map[string][]byte) *Verifier {
	return &Verifier{
		keys:       keys,
		nonceCache: NewNonceCache(MaxMessageAge * 2),
	}
}

// SignedMessage represents a signed API request
type SignedMessage struct {
	KeyID     string
	Timestamp int64
	Nonce     string
	Body      []byte
	MAC       []byte
	Version   uint8
}

// ParseSignedRequest extracts authentication from HTTP request
func (v *Verifier) ParseSignedRequest(r *http.Request) (*SignedMessage, error) {
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		return nil, errors.New("missing authorization header")
	}

	parts := strings.Split(authHeader, ":")
	if len(parts) != 5 {
		return nil, errors.New("malformed authorization header")
	}

	version, err := strconv.ParseUint(parts[0], 10, 8)
	if err != nil {
		return nil, fmt.Errorf("invalid version: %w", err)
	}

	timestamp, err := strconv.ParseInt(parts[1], 10, 64)
	if err != nil {
		return nil, fmt.Errorf("invalid timestamp: %w", err)
	}

	macBytes, err := hex.DecodeString(parts[4])
	if err != nil {
		return nil, fmt.Errorf("invalid mac encoding: %w", err)
	}

	return &SignedMessage{
		Version:   uint8(version),
		KeyID:     parts[2],
		Timestamp: timestamp,
		Nonce:     parts[3],
		MAC:       macBytes,
	}, nil
}

// computeMAC generates the expected MAC for a message
func (v *Verifier) computeMAC(key []byte, msg *SignedMessage, body []byte) []byte {
	mac := hmac.New(sha256.New, key)

	// Version-specific MAC computation
	header := make([]byte, 1+8+NonceSize)
	header[0] = msg.Version
	binary.BigEndian.PutUint64(header[1:9], uint64(msg.Timestamp))

	// Nonce is padded/truncated to NonceSize
	nonceBytes := []byte(msg.Nonce)
	if len(nonceBytes) > NonceSize {
		nonceBytes = nonceBytes[:NonceSize]
	}
	copy(header[9:], nonceBytes)

	mac.Write(header)
	mac.Write(body)

	return mac.Sum(nil)
}

// verifyMAC performs constant-time MAC comparison
// The MAC length field in the message header indicates the
// effective MAC length for backwards compatibility with
// clients that may use truncated MACs.
func (v *Verifier) verifyMAC(expected, provided []byte, msg *SignedMessage) bool {
	// Protocol version 1 supports variable-length MACs for
	// compatibility with legacy clients that truncate to 16 bytes.
	// Version 2+ always uses full 32-byte MACs.
	effectiveLength := MACLength
	if msg.Version == 1 {
		// Use the length of the provided MAC as the comparison length
		// to support legacy clients with shorter MACs
		effectiveLength = len(provided)
	}

	if effectiveLength <= 0 || effectiveLength > MACLength {
		return false
	}

	return hmac.Equal(expected[:effectiveLength], provided[:effectiveLength])
}

// Verify authenticates a signed request
func (v *Verifier) Verify(r *http.Request, body []byte) error {
	msg, err := v.ParseSignedRequest(r)
	if err != nil {
		return err
	}

	// Check timestamp freshness
	now := time.Now().Unix()
	if abs(now-msg.Timestamp) > MaxMessageAge {
		return ErrExpiredMessage
	}

	// Check nonce uniqueness
	if !v.nonceCache.Check(msg.Nonce) {
		return ErrReplayDetected
	}

	// Look up key
	v.mu.RLock()
	key, exists := v.keys[msg.KeyID]
	v.mu.RUnlock()
	if !exists {
		return ErrInvalidSignature
	}

	// Compute expected MAC
	expected := v.computeMAC(key, msg, body)

	// Verify
	if !v.verifyMAC(expected, msg.MAC, msg) {
		return ErrInvalidSignature
	}

	return nil
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}
